3. moment('2018-05-02 01:02:03.004 下午', ...)
4. moment('2018-05-02 01:02:03.004 AM', ..., 'en')
5. ja/ko variants.

Let me do that.

arguments.command:
cd /dayjs && node -e "
const moment = require('moment');
require('moment/locale/zh-cn');
require('moment/locale/ja');
require('moment/locale/ko');
const cases = [
  ['2018-05-02 01:02:03.004 AM','YYYY-MM-DD HH:mm:ss.SSS A','zh-cn'],
  ['2018-05-02 01:02:03.004 PM','YYYY-MM-DD HH:mm:ss.SSS A','zh-cn'],
  ['2018-05-02 01:02:03.004 上午','YYYY-MM-DD HH:mm:ss.SSS A','zh-cn'],
  ['2018-05-02 01:02:03.004 下午','YYYY-MM-DD HH:mm:ss.SSS A','zh-cn'],
  ['2018-05-02 01:02:03.004 AM','YYYY-MM-DD HH:mm:ss.SSS A','en'],
  ['2018-05-02 01:02:03.004 PM','YYYY-MM-DD HH:mm:ss.SSS A','en'],
  ['2018-05-02 01:02:03.004 午前','YYYY-MM-DD HH:mm:ss.SSS A','ja'],
  ['2018-05-02 01:02:03.004 午後','YYYY-MM-DD HH:mm:ss.SSS A','ja'],
  ['2018-05-02 01:02:03.004 오전','YYYY-MM-DD HH:mm:ss.SSS A','ko'],
  ['2018-05-02 01:02:03.004 오후','YYYY-MM-DD HH:mm:ss.SSS A','ko'],
];
for (const [i,f,l] of cases) {
  const m = moment(i,f,l);
  console.log(JSON.stringify([i.slice(-2), l, m.isValid(), m.isValid()? m.format('YYYY-MM-DD HH:mm:ss'):'invalid']));
}
"
